#### Phase 1: Infrastructure Foundation (Week 1)

**Step 1: Provision Azure Infrastructure**

Create resource group and provision core Azure services:

```bash
# PowerShell commands for Azure resource provisioning
$resourceGroup = "rg-webhook-platform-prod"
$location = "eastus"
$serviceBusNamespace = "sb-gainwell-webhooks-prod"
$cosmosAccount = "cosmos-webhook-subs-prod"
$keyVault = "kv-webhook-keys-prod"

# Create resource group
New-AzResourceGroup -Name $resourceGroup -Location $location

# Provision Service Bus Premium tier with 1 messaging unit
New-AzServiceBusNamespace -ResourceGroupName $resourceGroup -Name $serviceBusNamespace -Location $location -SkuName Premium -SkuCapacity 1

# Create webhook events topic with 7-day retention
New-AzServiceBusTopic -ResourceGroupName $resourceGroup -Namespace $serviceBusNamespace -Name "webhook-events" -DefaultMessageTimeToLive "P7D" -MaxSizeInMegabytes 5120

# Create topic subscription for dispatcher with dead letter queue
New-AzServiceBusSubscription -ResourceGroupName $resourceGroup -Namespace $serviceBusNamespace -Topic "webhook-events" -Name "webhook-dispatcher" -EnableDeadLetteringOnMessageExpiration $true -MaxDeliveryCount 3

# Provision Cosmos DB with SQL API
New-AzCosmosDBAccount -ResourceGroupName $resourceGroup -Name $cosmosAccount -Location $location -ApiKind GlobalDocumentDB -ConsistencyLevel "Session" -EnableAutomaticFailover $true

# Create Cosmos database and subscription container
New-AzCosmosDBSqlDatabase -ResourceGroupName $resourceGroup -AccountName $cosmosAccount -Name "WebhookPlatform"
New-AzCosmosDBSqlContainer -ResourceGroupName $resourceGroup -AccountName $cosmosAccount -DatabaseName "WebhookPlatform" -Name "Subscriptions" -PartitionKeyPath "/eventType" -Throughput 400

# Provision Key Vault with soft delete and purge protection
New-AzKeyVault -ResourceGroupName $resourceGroup -VaultName $keyVault -Location $location -EnableSoftDelete -EnablePurgeProtection

# Grant Key Vault access to managed identity (configured after AKS/Functions deployment)
```

**Step 2: Configure Service Bus Queue for Webhook Delivery**

Create delivery queue with retry and dead letter queue configuration:

```csharp
// C# code to configure Service Bus queue with advanced settings
using Azure.Messaging.ServiceBus.Administration;

var serviceBusClient = new ServiceBusAdministrationClient("<connection-string>");

// Create webhook delivery queue with retry and DLQ
var queueOptions = new CreateQueueOptions("webhook-delivery-queue")
{
    // Message retention: 7 days
    DefaultMessageTimeToLive = TimeSpan.FromDays(7),

    // Enable dead letter queue for expired messages
    DeadLetteringOnMessageExpiration = true,

    // Maximum delivery attempts before moving to DLQ
    MaxDeliveryCount = 3,

    // Lock duration for message processing
    LockDuration = TimeSpan.FromMinutes(5),

    // Enable duplicate detection for idempotency
    RequiresDuplicateDetection = true,
    DuplicateDetectionHistoryTimeWindow = TimeSpan.FromHours(24),

    // Enable partitioning for scalability
    EnablePartitioning = true,

    // Maximum queue size: 5GB
    MaxSizeInMegabytes = 5120
};

await serviceBusClient.CreateQueueAsync(queueOptions);

Console.WriteLine("Webhook delivery queue created successfully");
```

**Step 3: Set Up Cosmos DB Subscription Schema**

Define subscription document schema and create indexes:

```csharp
// C# Cosmos DB subscription model
public class WebhookSubscription
{
    [JsonProperty("id")]
    public string Id { get; set; } = $"sub_{Guid.NewGuid():N}";

    [JsonProperty("webhookUrl")]
    public string WebhookUrl { get; set; }

    [JsonProperty("eventType")]  // Partition key for efficient querying
    public string EventType { get; set; }

    [JsonProperty("eventTypes")]  // Array for multi-event subscriptions
    public List<string> EventTypes { get; set; }

    [JsonProperty("payloadFormat")]
    public string PayloadFormat { get; set; } = "JSON";  // JSON, FHIR_R4, X12

    [JsonProperty("hmacKeyRef")]
    public string HmacKeyRef { get; set; }  // Key Vault secret reference

    [JsonProperty("status")]
    public string Status { get; set; } = "active";  // active, paused, disabled

    [JsonProperty("filterCriteria")]
    public Dictionary<string, object> FilterCriteria { get; set; }  // Optional event filtering

    [JsonProperty("contactEmail")]
    public string ContactEmail { get; set; }

    [JsonProperty("createdAt")]
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

    [JsonProperty("updatedAt")]
    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;

    [JsonProperty("lastDeliveryAt")]
    public DateTime? LastDeliveryAt { get; set; }

    [JsonProperty("deliveryStats")]
    public DeliveryStatistics DeliveryStats { get; set; } = new();
}

public class DeliveryStatistics
{
    public int TotalDeliveries { get; set; }
    public int SuccessfulDeliveries { get; set; }
    public int FailedDeliveries { get; set; }
    public int RetryCount { get; set; }
    public double AverageLatencyMs { get; set; }
}

// Create composite index for efficient queries
var indexingPolicy = new IndexingPolicy
{
    IndexingMode = IndexingMode.Consistent,
    Automatic = true
};

// Composite index for status + event type queries
indexingPolicy.CompositeIndexes.Add(new Collection<CompositePath>
{
    new CompositePath { Path = "/status", Order = CompositePathSortOrder.Ascending },
    new CompositePath { Path = "/eventType", Order = CompositePathSortOrder.Ascending }
});

// Index for timestamp range queries
indexingPolicy.IncludedPaths.Add(new IncludedPath { Path = "/createdAt/*" });
indexingPolicy.IncludedPaths.Add(new IncludedPath { Path = "/lastDeliveryAt/*" });
```

