#### Phase 2: Webhook Management API (Week 2)

**Step 4: Implement Subscription Registration API**

Create REST API for webhook subscription CRUD operations:

```csharp
// ASP.NET Core Webhook Management API controller
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using Azure.Cosmos;
using Azure.Security.KeyVault.Secrets;
using System.Security.Cryptography;

[ApiController]
[Route("api/webhooks")]
[Authorize] // OAuth 2.0 authentication required
public class WebhookController : ControllerBase
{
    private readonly CosmosClient _cosmosClient;
    private readonly SecretClient _keyVaultClient;
    private readonly ILogger<WebhookController> _logger;

    public WebhookController(
        CosmosClient cosmosClient,
        SecretClient keyVaultClient,
        ILogger<WebhookController> logger)
    {
        _cosmosClient = cosmosClient;
        _keyVaultClient = keyVaultClient;
        _logger = logger;
    }

    /// <summary>
    /// Register new webhook subscription
    /// </summary>
    [HttpPost]
    [ProducesResponseType(typeof(WebhookRegistrationResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<IActionResult> RegisterWebhook([FromBody] WebhookRegistrationRequest request)
    {
        // Validate webhook URL format
        if (!Uri.IsWellFormedUriString(request.WebhookUrl, UriKind.Absolute))
        {
            return BadRequest(new { Error = "Invalid webhook URL format" });
        }

        // Enforce HTTPS for production environments
        var webhookUri = new Uri(request.WebhookUrl);
        if (webhookUri.Scheme != Uri.UriSchemeHttps && !_environment.IsDevelopment())
        {
            return BadRequest(new { Error = "HTTPS required for webhook URL in production" });
        }

        // Validate event types against allowed list
        var allowedEventTypes = await GetAllowedEventTypes();
        var invalidTypes = request.EventTypes.Except(allowedEventTypes).ToList();
        if (invalidTypes.Any())
        {
            return BadRequest(new { Error = $"Invalid event types: {string.Join(", ", invalidTypes)}" });
        }

        // Test webhook endpoint reachability
        var isReachable = await TestWebhookEndpoint(request.WebhookUrl);
        if (!isReachable)
        {
            return BadRequest(new { Error = "Webhook endpoint not reachable or returned non-2xx status" });
        }

        // Generate HMAC signing key
        var hmacKey = GenerateHmacKey();
        var subscription = new WebhookSubscription
        {
            Id = $"sub_{Guid.NewGuid():N}",
            WebhookUrl = request.WebhookUrl,
            EventType = request.EventTypes.First(), // Partition key
            EventTypes = request.EventTypes,
            PayloadFormat = request.PayloadFormat ?? "JSON",
            HmacKeyRef = $"webhook-hmac-{subscription.Id}",
            ContactEmail = request.ContactEmail,
            Status = "active"
        };

        // Store HMAC key in Key Vault
        var secretName = subscription.HmacKeyRef;
        await _keyVaultClient.SetSecretAsync(secretName, hmacKey);

        // Store subscription in Cosmos DB
        var container = _cosmosClient.GetContainer("WebhookPlatform", "Subscriptions");
        await container.CreateItemAsync(subscription, new PartitionKey(subscription.EventType));

        _logger.LogInformation(
            "Webhook subscription created: {SubscriptionId}, URL: {WebhookUrl}, Events: {EventTypes}",
            subscription.Id, subscription.WebhookUrl, string.Join(",", subscription.EventTypes));

        // Send test webhook to verify configuration
        await SendTestWebhook(subscription, hmacKey);

        // Return subscription details including HMAC secret (shown only once)
        return CreatedAtAction(nameof(GetWebhook), new { id = subscription.Id }, new WebhookRegistrationResponse
        {
            SubscriptionId = subscription.Id,
            WebhookUrl = subscription.WebhookUrl,
            EventTypes = subscription.EventTypes,
            HmacSecret = $"whsec_{hmacKey}", // Consumer must securely store this
            CreatedAt = subscription.CreatedAt,
            Status = subscription.Status
        });
    }

    /// <summary>
    /// Retrieve webhook subscription by ID
    /// </summary>
    [HttpGet("{id}")]
    [ProducesResponseType(typeof(WebhookSubscription), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> GetWebhook(string id)
    {
        // Query Cosmos DB for subscription
        var container = _cosmosClient.GetContainer("WebhookPlatform", "Subscriptions");

        try
        {
            // Note: Requires partition key for point-read, using query instead
            var query = new QueryDefinition("SELECT * FROM c WHERE c.id = @id")
                .WithParameter("@id", id);

            var iterator = container.GetItemQueryIterator<WebhookSubscription>(query);
            var response = await iterator.ReadNextAsync();
            var subscription = response.FirstOrDefault();

            if (subscription == null)
            {
                return NotFound(new { Error = $"Webhook subscription {id} not found" });
            }

            // Exclude HMAC key reference from response for security
            subscription.HmacKeyRef = "[redacted]";

            return Ok(subscription);
        }
        catch (CosmosException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return NotFound(new { Error = $"Webhook subscription {id} not found" });
        }
    }

    /// <summary>
    /// Update webhook subscription
    /// </summary>
    [HttpPut("{id}")]
    [ProducesResponseType(typeof(WebhookSubscription), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> UpdateWebhook(string id, [FromBody] WebhookUpdateRequest request)
    {
        var container = _cosmosClient.GetContainer("WebhookPlatform", "Subscriptions");

        // Retrieve existing subscription
        var query = new QueryDefinition("SELECT * FROM c WHERE c.id = @id")
            .WithParameter("@id", id);
        var iterator = container.GetItemQueryIterator<WebhookSubscription>(query);
        var response = await iterator.ReadNextAsync();
        var subscription = response.FirstOrDefault();

        if (subscription == null)
        {
            return NotFound(new { Error = $"Webhook subscription {id} not found" });
        }

        // Update mutable fields
        if (!string.IsNullOrEmpty(request.WebhookUrl))
        {
            subscription.WebhookUrl = request.WebhookUrl;
        }

        if (request.EventTypes != null && request.EventTypes.Any())
        {
            subscription.EventTypes = request.EventTypes;
        }

        if (!string.IsNullOrEmpty(request.Status))
        {
            subscription.Status = request.Status; // active, paused, disabled
        }

        subscription.UpdatedAt = DateTime.UtcNow;

        // Save updated subscription
        await container.ReplaceItemAsync(subscription, subscription.Id, new PartitionKey(subscription.EventType));

        _logger.LogInformation("Webhook subscription updated: {SubscriptionId}", id);

        return Ok(subscription);
    }

    /// <summary>
    /// Delete webhook subscription
    /// </summary>
    [HttpDelete("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> DeleteWebhook(string id)
    {
        var container = _cosmosClient.GetContainer("WebhookPlatform", "Subscriptions");

        // Retrieve subscription to get partition key
        var query = new QueryDefinition("SELECT * FROM c WHERE c.id = @id")
            .WithParameter("@id", id);
        var iterator = container.GetItemQueryIterator<WebhookSubscription>(query);
        var response = await iterator.ReadNextAsync();
        var subscription = response.FirstOrDefault();

        if (subscription == null)
        {
            return NotFound(new { Error = $"Webhook subscription {id} not found" });
        }

        // Delete subscription from Cosmos DB
        await container.DeleteItemAsync<WebhookSubscription>(id, new PartitionKey(subscription.EventType));

        // Delete HMAC key from Key Vault
        await _keyVaultClient.StartDeleteSecretAsync(subscription.HmacKeyRef);

        _logger.LogInformation("Webhook subscription deleted: {SubscriptionId}", id);

        return NoContent();
    }

    // Helper methods
    private string GenerateHmacKey()
    {
        using var rng = RandomNumberGenerator.Create();
        var keyBytes = new byte[32]; // 256-bit key
        rng.GetBytes(keyBytes);
        return Convert.ToBase64String(keyBytes);
    }

    private async Task<bool> TestWebhookEndpoint(string webhookUrl)
    {
        try
        {
            using var httpClient = new HttpClient { Timeout = TimeSpan.FromSeconds(10) };
            var response = await httpClient.SendAsync(new HttpRequestMessage(HttpMethod.Options, webhookUrl));
            return response.IsSuccessStatusCode;
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Webhook endpoint test failed for URL: {WebhookUrl}", webhookUrl);
            return false;
        }
    }

    private async Task SendTestWebhook(WebhookSubscription subscription, string hmacKey)
    {
        var testEvent = new
        {
            eventType = "test",
            eventId = $"evt_test_{Guid.NewGuid():N}",
            timestamp = DateTime.UtcNow,
            data = new { message = "Webhook test event" }
        };

        var payload = JsonSerializer.Serialize(testEvent);
        var signature = ComputeHmacSignature(payload, hmacKey);

        using var httpClient = new HttpClient { Timeout = TimeSpan.FromSeconds(30) };
        var request = new HttpRequestMessage(HttpMethod.Post, subscription.WebhookUrl)
        {
            Content = new StringContent(payload, Encoding.UTF8, "application/json")
        };

        request.Headers.Add("X-Event-Type", "test");
        request.Headers.Add("X-Event-ID", testEvent.eventId);
        request.Headers.Add("X-Webhook-Signature", $"sha256={signature}");

        try
        {
            var response = await httpClient.SendAsync(request);
            _logger.LogInformation(
                "Test webhook sent: {SubscriptionId}, Status: {StatusCode}",
                subscription.Id, (int)response.StatusCode);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Test webhook failed for subscription: {SubscriptionId}", subscription.Id);
        }
    }

    private string ComputeHmacSignature(string payload, string key)
    {
        var keyBytes = Convert.FromBase64String(key);
        using var hmac = new HMACSHA256(keyBytes);
        var payloadBytes = Encoding.UTF8.GetBytes(payload);
        var hashBytes = hmac.ComputeHash(payloadBytes);
        return Convert.ToHexString(hashBytes).ToLower();
    }
}

// Request/Response models
public class WebhookRegistrationRequest
{
    public string WebhookUrl { get; set; }
    public List<string> EventTypes { get; set; }
    public string PayloadFormat { get; set; }
    public string ContactEmail { get; set; }
}

public class WebhookRegistrationResponse
{
    public string SubscriptionId { get; set; }
    public string WebhookUrl { get; set; }
    public List<string> EventTypes { get; set; }
    public string HmacSecret { get; set; } // Shown only during registration
    public DateTime CreatedAt { get; set; }
    public string Status { get; set; }
}

public class WebhookUpdateRequest
{
    public string WebhookUrl { get; set; }
    public List<string> EventTypes { get; set; }
    public string Status { get; set; }
}
```

