#### Phase 3: Webhook Dispatcher Service (Week 2-3)

**Step 5: Implement Core Webhook Dispatcher**

Create dispatcher service consuming Service Bus events and delivering to webhook endpoints:

```csharp
// Webhook Dispatcher Service - Azure Functions or AKS hosted
using Azure.Messaging.ServiceBus;
using Azure.Cosmos;
using Azure.Security.KeyVault.Secrets;
using Polly;
using Polly.CircuitBreaker;
using Polly.Retry;

public class WebhookDispatcherService
{
    private readonly ServiceBusProcessor _processor;
    private readonly CosmosClient _cosmosClient;
    private readonly SecretClient _keyVaultClient;
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly ILogger<WebhookDispatcherService> _logger;
    private readonly AsyncRetryPolicy<HttpResponseMessage> _retryPolicy;
    private readonly AsyncCircuitBreakerPolicy<HttpResponseMessage> _circuitBreakerPolicy;

    public WebhookDispatcherService(
        ServiceBusClient serviceBusClient,
        CosmosClient cosmosClient,
        SecretClient keyVaultClient,
        IHttpClientFactory httpClientFactory,
        ILogger<WebhookDispatcherService> logger)
    {
        _processor = serviceBusClient.CreateProcessor("webhook-delivery-queue", new ServiceBusProcessorOptions
        {
            MaxConcurrentCalls = 10, // Process 10 webhooks concurrently
            AutoCompleteMessages = false // Manual complete after successful delivery
        });

        _cosmosClient = cosmosClient;
        _keyVaultClient = keyVaultClient;
        _httpClientFactory = httpClientFactory;
        _logger = logger;

        // Configure Polly retry policy: 3 attempts with exponential backoff
        _retryPolicy = Policy<HttpResponseMessage>
            .Handle<HttpRequestException>()
            .Or<TaskCanceledException>()
            .OrResult(r => r.StatusCode == System.Net.HttpStatusCode.TooManyRequests ||
                          r.StatusCode == System.Net.HttpStatusCode.ServiceUnavailable ||
                          (int)r.StatusCode >= 500)
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: attempt => TimeSpan.FromSeconds(Math.Pow(10, attempt - 1)), // 1s, 10s, 100s
                onRetry: (outcome, timespan, retryCount, context) =>
                {
                    _logger.LogWarning(
                        "Webhook delivery retry {RetryCount}: Status {StatusCode}, waiting {Delay}ms",
                        retryCount, outcome.Result?.StatusCode, timespan.TotalMilliseconds);
                });

        // Configure circuit breaker: Open after 5 consecutive failures, test recovery after 60s
        _circuitBreakerPolicy = Policy<HttpResponseMessage>
            .Handle<HttpRequestException>()
            .OrResult(r => !r.IsSuccessStatusCode)
            .CircuitBreakerAsync(
                handledEventsAllowedBeforeBreaking: 5,
                durationOfBreak: TimeSpan.FromSeconds(60),
                onBreak: (outcome, duration) =>
                {
                    _logger.LogError(
                        "Circuit breaker opened for webhook endpoint after 5 failures, duration: {Duration}s",
                        duration.TotalSeconds);
                },
                onReset: () =>
                {
                    _logger.LogInformation("Circuit breaker reset, webhook endpoint recovered");
                });

        _processor.ProcessMessageAsync += ProcessWebhookEventAsync;
        _processor.ProcessErrorAsync += ProcessErrorAsync;
    }

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        await _processor.StartProcessingAsync(cancellationToken);
        _logger.LogInformation("Webhook dispatcher service started");
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        await _processor.StopProcessingAsync(cancellationToken);
        _logger.LogInformation("Webhook dispatcher service stopped");
    }

    private async Task ProcessWebhookEventAsync(ProcessMessageEventArgs args)
    {
        var eventMessage = args.Message;
        var eventId = eventMessage.MessageId;
        var eventType = eventMessage.ApplicationProperties["EventType"].ToString();
        var payload = Encoding.UTF8.GetString(eventMessage.Body);

        _logger.LogInformation(
            "Processing webhook event: {EventId}, Type: {EventType}, Size: {PayloadSize} bytes",
            eventId, eventType, payload.Length);

        try
        {
            // Query subscriptions matching event type
            var subscriptions = await GetActiveSubscriptions(eventType);

            if (!subscriptions.Any())
            {
                _logger.LogWarning("No active subscriptions found for event type: {EventType}", eventType);
                await args.CompleteMessageAsync(eventMessage);
                return;
            }

            _logger.LogInformation(
                "Found {SubscriptionCount} subscriptions for event: {EventId}",
                subscriptions.Count, eventId);

            // Deliver webhook to all subscriptions in parallel
            var deliveryTasks = subscriptions.Select(sub =>
                DeliverWebhookAsync(sub, eventId, eventType, payload, args.CancellationToken));

            var deliveryResults = await Task.WhenAll(deliveryTasks);

            // Check if all deliveries succeeded
            var allSucceeded = deliveryResults.All(r => r);

            if (allSucceeded)
            {
                await args.CompleteMessageAsync(eventMessage);
                _logger.LogInformation("Webhook event processed successfully: {EventId}", eventId);
            }
            else
            {
                // Abandon message for redelivery if any delivery failed
                await args.AbandonMessageAsync(eventMessage);
                _logger.LogWarning("Some webhook deliveries failed, message abandoned for retry: {EventId}", eventId);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing webhook event: {EventId}", eventId);
            await args.AbandonMessageAsync(eventMessage);
        }
    }

    private async Task<List<WebhookSubscription>> GetActiveSubscriptions(string eventType)
    {
        var container = _cosmosClient.GetContainer("WebhookPlatform", "Subscriptions");

        // Query subscriptions where eventTypes array contains the event type and status is active
        var query = new QueryDefinition(
            "SELECT * FROM c WHERE ARRAY_CONTAINS(c.eventTypes, @eventType) AND c.status = 'active'")
            .WithParameter("@eventType", eventType);

        var subscriptions = new List<WebhookSubscription>();
        var iterator = container.GetItemQueryIterator<WebhookSubscription>(query);

        while (iterator.HasMoreResults)
        {
            var response = await iterator.ReadNextAsync();
            subscriptions.AddRange(response);
        }

        return subscriptions;
    }

    private async Task<bool> DeliverWebhookAsync(
        WebhookSubscription subscription,
        string eventId,
        string eventType,
        string payload,
        CancellationToken cancellationToken)
    {
        var startTime = DateTime.UtcNow;
        var subscriptionId = subscription.Id;
        var webhookUrl = subscription.WebhookUrl;

        try
        {
            // Retrieve HMAC key from Key Vault (cached for 15 minutes)
            var hmacKeyResponse = await _keyVaultClient.GetSecretAsync(subscription.HmacKeyRef, cancellationToken: cancellationToken);
            var hmacKey = hmacKeyResponse.Value.Value;

            // Compute HMAC signature
            var signature = ComputeHmacSignature(payload, hmacKey);

            // Build HTTP request
            var httpClient = _httpClientFactory.CreateClient();
            httpClient.Timeout = TimeSpan.FromSeconds(30);

            var request = new HttpRequestMessage(HttpMethod.Post, webhookUrl)
            {
                Content = new StringContent(payload, Encoding.UTF8, "application/json")
            };

            request.Headers.Add("X-Event-Type", eventType);
            request.Headers.Add("X-Event-ID", eventId);
            request.Headers.Add("X-Webhook-Signature", $"sha256={signature}");
            request.Headers.Add("X-Delivery-Attempt", "1");

            // Execute delivery with retry and circuit breaker policies
            var response = await _retryPolicy.ExecuteAsync(async () =>
            {
                return await _circuitBreakerPolicy.ExecuteAsync(async () =>
                {
                    return await httpClient.SendAsync(request, cancellationToken);
                });
            });

            var latency = (DateTime.UtcNow - startTime).TotalMilliseconds;

            if (response.IsSuccessStatusCode)
            {
                _logger.LogInformation(
                    "Webhook delivered successfully: Event {EventId}, Subscription {SubscriptionId}, Status {StatusCode}, Latency {Latency}ms",
                    eventId, subscriptionId, (int)response.StatusCode, latency);

                // Update delivery statistics
                await UpdateDeliveryStatistics(subscription, success: true, latency);

                return true;
            }
            else
            {
                _logger.LogWarning(
                    "Webhook delivery failed: Event {EventId}, Subscription {SubscriptionId}, Status {StatusCode}, Latency {Latency}ms",
                    eventId, subscriptionId, (int)response.StatusCode, latency);

                await UpdateDeliveryStatistics(subscription, success: false, latency);

                return false;
            }
        }
        catch (BrokenCircuitException ex)
        {
            _logger.LogError(
                "Circuit breaker open for subscription {SubscriptionId}, skipping delivery",
                subscriptionId);
            return false;
        }
        catch (Exception ex)
        {
            var latency = (DateTime.UtcNow - startTime).TotalMilliseconds;

            _logger.LogError(ex,
                "Webhook delivery exception: Event {EventId}, Subscription {SubscriptionId}, Latency {Latency}ms",
                eventId, subscriptionId, latency);

            await UpdateDeliveryStatistics(subscription, success: false, latency);

            return false;
        }
    }

    private string ComputeHmacSignature(string payload, string key)
    {
        var keyBytes = Convert.FromBase64String(key);
        using var hmac = new HMACSHA256(keyBytes);
        var payloadBytes = Encoding.UTF8.GetBytes(payload);
        var hashBytes = hmac.ComputeHash(payloadBytes);
        return Convert.ToHexString(hashBytes).ToLower();
    }

    private async Task UpdateDeliveryStatistics(WebhookSubscription subscription, bool success, double latency)
    {
        subscription.DeliveryStats.TotalDeliveries++;

        if (success)
        {
            subscription.DeliveryStats.SuccessfulDeliveries++;
        }
        else
        {
            subscription.DeliveryStats.FailedDeliveries++;
        }

        // Update average latency using exponential moving average
        subscription.DeliveryStats.AverageLatencyMs =
            (subscription.DeliveryStats.AverageLatencyMs * 0.9) + (latency * 0.1);

        subscription.LastDeliveryAt = DateTime.UtcNow;

        // Update subscription in Cosmos DB
        var container = _cosmosClient.GetContainer("WebhookPlatform", "Subscriptions");
        await container.ReplaceItemAsync(subscription, subscription.Id, new PartitionKey(subscription.EventType));
    }

    private Task ProcessErrorAsync(ProcessErrorEventArgs args)
    {
        _logger.LogError(args.Exception,
            "Service Bus processing error: Source {ErrorSource}, Entity {EntityPath}",
            args.ErrorSource, args.EntityPath);
        return Task.CompletedTask;
    }
}
