**Step 6: Implement Event Publisher SDK**

Create SDK for business services to publish webhook events:

```csharp
// Webhook Event Publisher SDK - NuGet package for product teams
using Azure.Messaging.ServiceBus;
using System.Text.Json;

public interface IWebhookPublisher
{
    Task PublishAsync<T>(string eventType, T eventData, CancellationToken cancellationToken = default);
}

public class WebhookPublisher : IWebhookPublisher
{
    private readonly ServiceBusSender _sender;
    private readonly ILogger<WebhookPublisher> _logger;

    public WebhookPublisher(ServiceBusClient serviceBusClient, ILogger<WebhookPublisher> logger)
    {
        _sender = serviceBusClient.CreateSender("webhook-events");
        _logger = logger;
    }

    public async Task PublishAsync<T>(string eventType, T eventData, CancellationToken cancellationToken = default)
    {
        var eventId = $"evt_{Guid.NewGuid():N}";
        var timestamp = DateTime.UtcNow;

        // Wrap event in CloudEvents envelope
        var cloudEvent = new
        {
            specversion = "1.0",
            type = eventType,
            source = "gainwell/enterprise",
            id = eventId,
            time = timestamp,
            datacontenttype = "application/json",
            data = eventData
        };

        var payload = JsonSerializer.Serialize(cloudEvent);
        var message = new ServiceBusMessage(payload)
        {
            MessageId = eventId,
            ContentType = "application/cloudevents+json"
        };

        message.ApplicationProperties["EventType"] = eventType;
        message.ApplicationProperties["Timestamp"] = timestamp;

        await _sender.SendMessageAsync(message, cancellationToken);

        _logger.LogInformation(
            "Webhook event published: {EventId}, Type: {EventType}, Size: {Size} bytes",
            eventId, eventType, payload.Length);
    }
}

// Usage example in business service
public class ClaimsService
{
    private readonly IWebhookPublisher _webhookPublisher;

    public ClaimsService(IWebhookPublisher webhookPublisher)
    {
        _webhookPublisher = webhookPublisher;
    }

    public async Task AdjudicateClaimAsync(string claimId)
    {
        // Business logic to adjudicate claim
        var claim = await ProcessClaimAdjudication(claimId);

        // Publish webhook event
        await _webhookPublisher.PublishAsync("claims.adjudicated", new
        {
            claimId = claim.Id,
            providerId = claim.ProviderId,
            status = claim.Status,
            amount = claim.ApprovedAmount,
            adjudicationDate = claim.AdjudicatedAt
        });
    }
}
