#### Health Check Endpoints

Webhook platform exposes health check endpoints for Kubernetes liveness/readiness probes:

```csharp
// Health check implementation
[Route("health")]
[ApiController]
public class HealthController : ControllerBase
{
    private readonly ServiceBusClient _serviceBusClient;
    private readonly CosmosClient _cosmosClient;
    private readonly SecretClient _keyVaultClient;

    [HttpGet("live")]
    public IActionResult Liveness()
    {
        // Liveness probe: Process is running
        return Ok(new { status = "healthy", timestamp = DateTime.UtcNow });
    }

    [HttpGet("ready")]
    public async Task<IActionResult> Readiness()
    {
        var checks = new List<(string name, bool healthy, string message)>();

        // Check Service Bus connectivity
        try
        {
            var sender = _serviceBusClient.CreateSender("webhook-events");
            await sender.SendMessageAsync(new ServiceBusMessage(Encoding.UTF8.GetBytes("health-check")));
            checks.Add(("ServiceBus", true, "Connected"));
        }
        catch (Exception ex)
        {
            checks.Add(("ServiceBus", false, ex.Message));
        }

        // Check Cosmos DB connectivity
        try
        {
            var container = _cosmosClient.GetContainer("WebhookPlatform", "Subscriptions");
            await container.ReadContainerAsync();
            checks.Add(("CosmosDB", true, "Connected"));
        }
        catch (Exception ex)
        {
            checks.Add(("CosmosDB", false, ex.Message));
        }

        // Check Key Vault connectivity
        try
        {
            await _keyVaultClient.GetSecretAsync("health-check-secret");
            checks.Add(("KeyVault", true, "Connected"));
        }
        catch (Exception ex)
        {
            checks.Add(("KeyVault", false, ex.Message));
        }

        var allHealthy = checks.All(c => c.healthy);
        var status = allHealthy ? "healthy" : "unhealthy";

        return allHealthy
            ? Ok(new { status, checks, timestamp = DateTime.UtcNow })
            : StatusCode(503, new { status, checks, timestamp = DateTime.UtcNow });
    }

    [HttpGet("integrations")]
    public async Task<IActionResult> IntegrationHealth()
    {
        // Detailed health check for monitoring dashboards
        var container = _cosmosClient.GetContainer("WebhookPlatform", "Subscriptions");

        var query = new QueryDefinition("SELECT * FROM c WHERE c.status = 'active'");
        var iterator = container.GetItemQueryIterator<WebhookSubscription>(query);

        var subscriptions = new List<WebhookSubscription>();
        while (iterator.HasMoreResults)
        {
            var response = await iterator.ReadNextAsync();
            subscriptions.AddRange(response);
        }

        var health = new
        {
            activeSubscriptions = subscriptions.Count,
            subscriptionsByStatus = subscriptions.GroupBy(s => s.Status)
                .ToDictionary(g => g.Key, g => g.Count()),
            subscriptionsWithFailures = subscriptions
                .Where(s => s.DeliveryStats.FailedDeliveries > 0)
                .Select(s => new
                {
                    subscriptionId = s.Id,
                    webhookUrl = s.WebhookUrl,
                    successRate = s.DeliveryStats.TotalDeliveries > 0
                        ? (double)s.DeliveryStats.SuccessfulDeliveries / s.DeliveryStats.TotalDeliveries
                        : 0,
                    lastDelivery = s.LastDeliveryAt
                })
                .OrderBy(s => s.successRate)
                .Take(10)
                .ToList(),
            timestamp = DateTime.UtcNow
        };

        return Ok(health);
    }
}
```

