```csharp
// HIE webhook handler (C# ASP.NET Core)
[HttpPost("/webhooks/encounters")]
public async Task<IActionResult> HandleEncounterWebhook()
{
    // Read webhook payload
    using var reader = new StreamReader(Request.Body);
    var payload = await reader.ReadToEndAsync();

    // Verify HMAC signature
    if (!VerifyWebhookSignature(payload, Request.Headers["X-Webhook-Signature"]))
    {
        return Unauthorized(new { error = "Invalid signature" });
    }

    var cloudEvent = JsonSerializer.Deserialize<CloudEvent<FhirEncounter>>(payload);
    var encounter = cloudEvent.Data;
    var eventId = Request.Headers["X-Event-ID"].ToString();

    // Check for duplicate
    if (await _eventStore.IsDuplicateAsync(eventId))
    {
        return Ok(new { status = "acknowledged", message = "Duplicate event" });
    }

    await _eventStore.StoreProcessedEventAsync(eventId);

    // Queue for async processing
    await _queueService.EnqueueAsync(new EncounterEvent
    {
        EventId = eventId,
        EncounterId = encounter.Id,
        PatientId = encounter.Subject.Identifier.Value,
        EncounterType = encounter.Class.Code,
        AdmissionDateTime = encounter.Period.Start,
        Facility = encounter.ServiceProvider.Display,
        EventType = cloudEvent.Type
    });

    // Acknowledge immediately
    return Accepted(new { status = "accepted", eventId });
}

// Background processing service
public class EncounterProcessor : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            var event = await _queueService.DequeueAsync(stoppingToken);

            // Match patient against MPI
            var patient = await _mpiService.FindPatientAsync(event.PatientId);

            if (patient != null)
            {
                // Assign care coordinator based on patient risk score
                var coordinator = await _careTeamService.AssignCoordinatorAsync(patient.Id);

                // Create care coordination task
                await _careTaskService.CreateTaskAsync(new CareTask
                {
                    PatientId = patient.Id,
                    CoordinatorId = coordinator.Id,
                    TaskType = event.EncounterType == "IMP"
                        ? "Hospital Admission Follow-up"
                        : "Emergency Department Follow-up",
                    Priority = patient.RiskScore > 75 ? "High" : "Medium",
                    DueDate = DateTime.UtcNow.AddHours(2), // Contact within 2 hours
                    Description = $"Patient admitted to {event.Facility} on {event.AdmissionDateTime}. " +
                                $"Coordinate discharge planning and community resources."
                });

                // Send mobile app notification to coordinator
                await _notificationService.NotifyCoordinatorAsync(coordinator.Id,
                    $"New hospital admission: {patient.DisplayName} at {event.Facility}");

                _logger.LogInformation(
                    "Care coordination task created for encounter {EncounterId}, patient {PatientId}, coordinator {CoordinatorId}",
                    event.EncounterId, patient.Id, coordinator.Id);
            }
        }
    }
}
```

**After (Webhook-Based Real-Time Integration)**: Hospital encounter claims/encounters processed by Gainwell within 4-8 hours of admission (electronic submission + adjudication), webhook delivered to HIE within 5-10 seconds of processing, care coordinator notified within 2 minutes via mobile app push notification.

Results and Benefits:

**Reduced Notification Latency** (24-36 hour improvement):
- Hospital admission 10:00 AM → Claim submitted 2:00 PM → Gainwell processes 6:00 PM → Webhook delivered 6:00:08 PM → Care coordinator notified 6:02 PM via mobile app—total 8 hours admission-to-notification vs 47 hours with batch files (83% latency reduction)
- Emergency department visits processed within 2-4 hours enabling same-day care coordinator outreach—average 3.5 hours ED visit-to-coordinator contact vs 24-36 hours with batch files
- Hospital discharge notifications delivered real-time enabling immediate post-discharge follow-up—care coordinators contact members within 24 hours of discharge (vs 48-72 hours) improving medication reconciliation and appointment scheduling

**Care Coordination Effectiveness** (35% improvement in timely interventions):
- Care coordinators now reach hospitalized members during 70% of hospital stay vs 40% with batch files—enables discharge planning, medication management, community resource coordination before discharge
- High-risk member interventions increased 45%—risk stratification triggers automatic care coordinator assignment for members with chronic conditions (diabetes, heart failure, COPD), coordinators proactively engage during hospitalization
- Care team collaboration improved—hospital social workers, HIE care coordinators, primary care providers notified simultaneously via webhook fan-out enabling coordinated discharge planning

**Readmission Reduction** ($840K annual cost avoidance):
- 30-day readmission rate decreased from 18.5% to 14.2% (23% relative reduction) attributed to improved discharge planning and post-discharge follow-up—real-time admission notifications enable proactive care coordination
- 68 fewer monthly readmissions for 180K member population—68 × $12,400 average readmission cost = $843,200 monthly avoided costs, $10.1M annualized
- Post-discharge medication adherence improved 15%—care coordinators conduct medication reconciliation calls within 24 hours ensuring members have prescriptions filled and understand instructions

**Preventable ED Visit Reduction** ($648K annual savings):
- Monthly preventable ED visits reduced from 242 to 188 (22% reduction)—real-time admission alerts enable rapid outreach for frequent ED utilizers connecting them to primary care and community resources
- Care coordinators contact frequent ED users within hours of ED visit discharge—"warm handoff" to primary care appointments scheduled within 48 hours preventing return ED visits
- 54 avoided monthly ED visits × $2,400 average cost = $129,600 monthly savings, $1.6M annualized

**Operational Efficiency** (50% faster care coordinator response):
- Average time from hospital admission to care coordinator outreach: 8 hours (real-time webhook) vs 48 hours (batch files)—400% improvement enabling interventions during hospitalization rather than post-discharge
- Care coordinator productivity increased 25%—real-time notifications eliminate manual daily file processing (2 hours/day reviewing batch files), coordinators focus on member engagement
- Mobile app push notifications ensure coordinators aware of admissions immediately—no missed notifications due to email delays or login requirements

**Technical Reliability and FHIR Compliance** (99.8% delivery success):
- 8,000-12,000 daily encounter webhooks delivered with 99.8% success rate—16 daily failed deliveries automatically retried with 94% retry success (15 recovered, 1 DLQ)
- FHIR R4 payload format enables seamless HIE integration—no custom data transformation logic required, encounter resources directly consumed by FHIR-native HIE platform
- HL7 FHIR subscription framework compliance prepares HIE for upcoming CMS interoperability requirements—webhook pattern aligned with payer-to-payer data exchange standards

**Quantified ROI** (Net $11.4M annual value):
- **Readmission cost avoidance**: $10.1M annually (68 monthly readmissions × $12,400 cost)
- **Preventable ED visit savings**: $1.6M annually (54 monthly visits × $2,400 cost)
